static obj_t        *g_obj;
static pthread_once_t g_once = PTHREAD_ONCE_INIT;

static void init_obj(void) { g_obj = obj_create(); }

obj_t *obj_get(void) {
    pthread_once(&g_once, init_obj);   /* first caller builds, others wait */
    return g_obj;
}
/* C11: static once_flag f = ONCE_FLAG_INIT; call_once(&f, init_obj); */
